def _memory_slug(path: str) -> str | None:
    """Return the bare memory item ID (without .md) if path points to a memory file."""
    m = _MEMORY_FILE_RE.search(path)
    if not m:
        return None
    filename = m.group(1)
    return filename[:-3] if filename.endswith(".md") else filename


